equation_logic_text:
// Logic template
var calc_output = [];

var a = parseFloat(a);
var b = parseFloat(b);
var c = parseFloat(c);
var d = parseFloat(d);
var e = parseFloat(e);
var f = parseFloat(f);
var g = parseFloat(g);
var h = parseFloat(h);
var i = parseFloat(i);

if (UOMSYSTEM == false) { 
    // albumin: g/L -> g/dL
    var b = b/10; 
    // bilirubin: µmol/L -> mg/dL
    var c = c/17.1;
}

// Knots
var d_k1 = 74, d_k2 = 153, d_k3 = 269;
var b_k1 = 2.7, b_k2 = 3.7, b_k3 = 4.4;

// Albumin splines 
var albumin_sp1 = b;
var albumin_sp2 = 0;

var gt1 = 0; if (b > b_k1) gt1 = 1;
var gt2 = 0; if (b > b_k2) gt2 = 1;
var gt3 = 0; if (b > b_k3) gt3 = 1;

var term1 = Math.pow(b - b_k1, 3) * gt1;

var inner =
  (Math.pow(b - b_k2, 3) * gt2 * (b_k3 - b_k1)) -
  (Math.pow(b - b_k3, 3) * gt3 * (b_k2 - b_k1));

var term2 = (1 / (b_k3 - b_k2)) * inner;

var numerator = term1 - term2;
var denom = Math.pow(b_k3 - b_k1, 2);

albumin_sp2 = numerator / denom;

// Platelets splines 
var platelets_sp1 = d;
var platelets_sp2 = 0;

var gt1p = 0; if (d > d_k1) gt1p = 1;
var gt2p = 0; if (d > d_k2) gt2p = 1;
var gt3p = 0; if (d > d_k3) gt3p = 1;

var term1p = Math.pow(d - d_k1, 3) * gt1p;

var innerp =
  (Math.pow(d - d_k2, 3) * gt2p * (d_k3 - d_k1)) -
  (Math.pow(d - d_k3, 3) * gt3p * (d_k2 - d_k1));

var term2p = (1 / (d_k3 - d_k2)) * innerp;

var numeratorp = term1p - term2p;
var denomp = Math.pow(d_k3 - d_k1, 2);

platelets_sp2 = numeratorp / denomp;

// Bilirubin splines (for 90-day decompensation)
var c_k1 = 0.39, c_k2 = 0.75, c_k3 = 1.8;

var bili_sp1 = c;
var bili_sp2 = 0;

var gt1c = 0; if (c > c_k1) gt1c = 1;
var gt2c = 0; if (c > c_k2) gt2c = 1;
var gt3c = 0; if (c > c_k3) gt3c = 1;

var term1c = Math.pow(c - c_k1, 3) * gt1c;
var innerc =
  (Math.pow(c - c_k2, 3) * gt2c * (c_k3 - c_k1)) -
  (Math.pow(c - c_k3, 3) * gt3c * (c_k2 - c_k1));
var term2c = (1 / (c_k3 - c_k2)) * innerc;

bili_sp2 = (term1c - term2c) / Math.pow(c_k3 - c_k1, 2);

// Surgery type indicators (0/1)
var surgery_laparo = 0;
var surgery_open_abdominal = 0;
var surgery_abdominal_wall = 0;
var surgery_vascular = 0;
var surgery_major_orthopedic = 0;
var surgery_chest_cardiac = 0;

if (i == 0) {
  surgery_laparo = 1;
} else if (i == 1) {
  surgery_open_abdominal = 1;
} else if (i == 2) {
  surgery_abdominal_wall = 1;
} else if (i == 3) {
  surgery_vascular = 1;
} else if (i == 4) {
  surgery_major_orthopedic = 1;
} else if (i == 5) {
  surgery_chest_cardiac = 1;
}

// Log-odds
var logodds_30 =
  -5.472096
  + 1.061725  * g
  + 0.927904  * h
  + 1.56071   * surgery_open_abdominal
  + 0.7418021 * surgery_abdominal_wall
  + 0.9165415 * surgery_vascular
  + 1.464183  * surgery_major_orthopedic
  + 1.893621  * surgery_chest_cardiac
  - 0.0075185 * platelets_sp1
  + 0.0036657 * platelets_sp2
  - 0.5181509 * albumin_sp1
  - 1.000672  * albumin_sp2
  + 0.1448936 * c
  - 0.7541669 * e
  + 0.8268748 * f;

var logodds_90 =
  -7.381628
  + 0.6891587 * g
  + 0.6246303 * h
  + 0.0365738 * a
  + 1.349889  * surgery_open_abdominal
  + 0.2480613 * surgery_abdominal_wall
  + 1.054497  * surgery_vascular
  + 1.067452  * surgery_major_orthopedic
  + 1.26527   * surgery_chest_cardiac
  - 0.4851036 * albumin_sp1
  - 0.9821122 * albumin_sp2
  + 0.82691   * f;

var logodds_180 =
  -6.169259
  + 0.850114  * g
  + 0.0293034 * a
  + 0.8838124 * surgery_open_abdominal
  + 0.197697  * surgery_abdominal_wall
  + 0.4630691 * surgery_vascular
  + 0.1229086 * surgery_major_orthopedic
  + 0.4320639 * surgery_chest_cardiac
  - 0.003719  * platelets_sp1
  - 0.0004196 * platelets_sp2
  - 0.4560354 * albumin_sp1
  - 0.4166421 * albumin_sp2
  - 0.5176601 * e;

// Logistic transform
var ex30 = Math.exp(logodds_30);
var ex90 = Math.exp(logodds_90);
var ex180 = Math.exp(logodds_180);

var p30_unadj  = ex30  / (1 + ex30);
var p90_unadj  = ex90  / (1 + ex90);
var p180_unadj = ex180 / (1 + ex180);

// Final probabilities
var p30_adj  = p30_unadj;
var p90_adj  = 1 - (1 - p30_adj) * (1 - p90_unadj);
var p180_adj = 1 - (1 - p30_adj) * (1 - p90_unadj) * (1 - p180_unadj);

var pct30 = p30_adj * 100;
var pct90 = p90_adj * 100;
var pct180 = p180_adj * 100;

// 90-day decompensation log-odds (match site)
var logodds_decomp90 =
  -2.287235
  + 0.2988972 * g
  + 0.5076108 * h
  + 0.6117639 * surgery_open_abdominal
  - 0.1508734 * surgery_abdominal_wall
  - 0.4641384 * surgery_vascular
  - 0.3442967 * surgery_major_orthopedic
  - 0.1648213 * surgery_chest_cardiac
  - 0.0054196 * platelets_sp1
  + 0.0021578 * platelets_sp2
  - 0.4460345 * albumin_sp1
  - 0.4612017 * albumin_sp2
  + 1.361681  * bili_sp1
  - 1.746094  * bili_sp2
  - 0.1820302 * e
  + 0.2481661 * f
  + 0.0069088 * a;

var exd = Math.exp(logodds_decomp90);
var p_decomp90 = exd / (1 + exd);
var pct_decomp90 = p_decomp90 * 100;

// Site-like rounding to 1 decimal (no function)
var t30 = Math.round(pct30 * 10) / 10;
var pct30_1dp = (t30 % 1 === 0) ? t30.toFixed(1) : String(t30);

var t90 = Math.round(pct90 * 10) / 10;
var pct90_1dp = (t90 % 1 === 0) ? t90.toFixed(1) : String(t90);

var t180 = Math.round(pct180 * 10) / 10;
var pct180_1dp = (t180 % 1 === 0) ? t180.toFixed(1) : String(t180);

var td = Math.round(pct_decomp90 * 10) / 10;
var pct_decomp90_1dp = (td % 1 === 0) ? td.toFixed(1) : String(td);

// Out of range warning
var warn = "";

var warn_flag = 0;

if (a < 40 || a > 85) warn_flag = 1;
if (b < 1.5 || b > 5.0) warn_flag = 1;
if (c < 0.2 || c > 5.0) warn_flag = 1;
if (d < 30 || d > 450) warn_flag = 1;

if (warn_flag == 1) {
  warn = "<br/><br/>Prediction may be less accurate due to values outside derivation ranges.";
}

// Output
calc_output.push({
    name: 'mini',
    value: pct30_1dp,
    value_text: '%',
    message: '30-day mortality by VOCAL-Penn Score' + warn
});
calc_output.push({
    name: '10652_VOCAL-Penn Score_result',
    value:  pct30_1dp,
    value_text: '%',
    message: '30-day mortality' + '<br/><br/>90-day mortality: ' + pct90_1dp + '%' + '<br/>180-day mortality: ' + pct180_1dp + '%' + warn
});
calc_output.push({
    name: '10652_VOCAL-Penn Score_result',
    value:  pct_decomp90_1dp,
    value_text: '%',
    message: '90-day decompensation risk' 
});
